                    with m1:
                        data_m  = st.date_input("Data")
                        causa_m = st.selectbox("Causa", ["Doenca","Acidente","Desaparecimento","Predador","Outras"])
                    with m2:
                        custo_m = st.number_input("Custo da perda (R$)", 0.0)
