                if nome_nl:
                    lote_id = adicionar_lote(nome_nl, "", str(data_nl), qtd_c2, qtd_r2, trp_nl)
                    registrar_auditoria(u["id"], "criar_lote", "lotes", lote_id, nome_nl)
                    st.success(f"Lote '{nome_nl}' criado!")
